// tools/get_rates.ts · one tool, one schema, one disclaimer
export const getRates = tool({
  name: "get_rates",
  description: "Borrow and savings rates per asset and chain. Figures as of a block; not advice.",
  input: z.object({
    chain: z.enum(["base", "arbitrum", "ethereum"]),
    asset: z.string().optional(),            // every asset when omitted
  }),
  async run({ chain, asset }) {
    const { block, rates, age } = await indexer(chain).rates(asset);
    return {
      block, rates,
      stale: age > 300,                       // seconds since the newest block
      note: age > 300 ? `Figures as of block ${block}, ${age} s old.` : undefined,
    };
  },
});
